// Generated by `pnpm nx g @app/generators:topic explorer.window`. It holds the topic to the kit
// invariants and to the live frames it travels in. Do not weaken it. The AC-17 to AC-20 tests below
// the generated ones drive the source through a real LiveHub (M0-48 slice E).
import {
  ClientFrameSchema,
  ConnectionIdSchema,
  ServerFrameSchema,
  checkRegistry,
  encodeObjectKey,
  explorerWindowTopic,
  type ClientFrame,
  type ServerFrame,
} from '@app/contracts';
import { createTestPrincipal } from '@app/kernel';
import {
  createTopicRegistry,
  LiveHub,
  type LiveHubOptions,
  type TopicSource,
} from '@app/live';
import type { MgmtGetRequest, MgmtReadPort } from '@app/ports';
import { describe, expect, it } from 'vitest';

import {
  createWindowSource,
  type WindowItem,
  type WindowParams,
  type WindowSource,
} from './internal/window-source';
import { createExplorerModule } from './module';
import {
  createExplorerFakeDeps,
  createScriptedBroker,
  type ExplorerFakeDeps,
  type ScriptedBroker,
} from './testing';
import {
  sampleItem,
  sampleParams,
} from './topics.explorer-window-topic.fixture';

const topic = explorerWindowTopic;

describe('explorer.window', () => {
  it('AC-1 the contract passes the kit invariants: bounded ring, keyed, no secret', () => {
    expect(checkRegistry({ actions: [], topics: [topic] })).toEqual([]);
    // Bounded by items and by bytes (I-6): whatever the numbers are, both are finite.
    expect(Number.isSafeInteger(topic.ring.items) && topic.ring.items > 0).toBe(
      true,
    );
    expect(Number.isSafeInteger(topic.ring.bytes) && topic.ring.bytes > 0).toBe(
      true,
    );
  });

  it('AC-2 the sample params and item fit the schemas, and travel in live frames', () => {
    const item = topic.item.parse(sampleItem);

    expect(topic.params.safeParse(sampleParams).success).toBe(true);
    expect(
      ClientFrameSchema.safeParse({
        t: 'sub',
        sid: 1,
        topic: topic.id,
        params: sampleParams,
        credit: 16,
      }).success,
    ).toBe(true);
    expect(
      ServerFrameSchema.safeParse({
        t: 'snapshot',
        sid: 1,
        seq: 1,
        items: [item],
      }).success,
    ).toBe(true);
    expect(
      ServerFrameSchema.safeParse({
        t: 'delta',
        sid: 1,
        seq: 2,
        upserts: [item],
        removes: [topic.key?.(item) ?? ''],
      }).success,
    ).toBe(true);
  });

  it('AC-3 an item has one stable key, so coalescing and removals agree', () => {
    const first = topic.key?.(topic.item.parse(sampleItem));
    const second = topic.key?.(topic.item.parse({ ...sampleItem }));

    expect(typeof first).toBe('string');
    expect(first).toBe(second);
  });

  it('AC-4 the module declares the topic', () => {
    expect(createExplorerModule(createExplorerFakeDeps()).topics).toContain(
      topic,
    );
  });

  it('AC-5 a provider feeds the topic: the module hands its source to the composition root', () => {
    const { topicSources } = createExplorerModule(createExplorerFakeDeps());

    expect(topicSources.map((binding) => binding.def)).toEqual([topic]);
  });
});

const cid = ConnectionIdSchema.parse('c1');
const queueName = (i: number) => `queue-${String(i).padStart(6, '0')}`;
interface Item {
  key: string;
  version: number;
  row?: Record<string, unknown>;
}

/** A scripted broker whose answers a spec changes between sweeps: hide queues, set their counts. */
function setup(
  queueCount: number,
  vhostCount: number,
  exchanges = 0,
  connections = 0,
) {
  const broker: ScriptedBroker = createScriptedBroker({
    queueCount,
    vhostCount,
    exchangesPerVhost: exchanges,
    connectionCount: connections,
  });
  const hidden = new Set<string>();
  const messages = new Map<string, number>();
  const mgmt: MgmtReadPort = {
    async get<T>(request: MgmtGetRequest<T>, signal: AbortSignal) {
      const out = await broker.read.get(request, signal);
      const page = out as { items?: { name: string }[] };
      if (
        /^\/api\/(queues\/|exchanges\/|connections$)/.test(request.path) &&
        page.items
      ) {
        page.items = page.items
          .filter((item) => !hidden.has(item.name))
          .map((item) =>
            messages.has(item.name)
              ? { ...item, messages: messages.get(item.name) }
              : item,
          );
      }
      return out;
    },
    stream: (request, signal) => broker.read.stream(request, signal),
  };
  const deps = createExplorerFakeDeps({ mgmt });
  return {
    broker,
    hidden,
    messages,
    deps,
    sweep: () => deps.sweeper.sweepNow(cid, new AbortController().signal),
    keyOf: (i: number) =>
      encodeObjectKey(broker.vhosts[i % vhostCount] ?? '', queueName(i)),
  };
}

/** The source as the hub sees it, recording what it publishes and how often it is started. */
function spied(source: WindowSource) {
  const published: WindowItem[] = [];
  const removed: string[] = [];
  let started = 0;
  const wrapped: TopicSource<WindowParams, WindowItem> = {
    snapshot: (params, who) => source.snapshot(params, who),
    subscribe: (params, who, sink) => {
      started += 1;
      return source.subscribe(params, who, {
        ...sink,
        publish: (item, bytes) => {
          published.push(item);
          sink.publish(item, bytes);
        },
        remove: (key) => {
          removed.push(key);
          sink.remove(key);
        },
      });
    },
  };
  return { source: wrapped, published, removed, started: () => started };
}

/** A real LiveHub over the source, on the manual clock of the fakes, and clients that read its frames. */
function open(
  deps: ExplorerFakeDeps,
  source: TopicSource<WindowParams, WindowItem>,
  options: Partial<LiveHubOptions> = {},
) {
  const topics = createTopicRegistry();
  topics.register(topic, source);
  const hub = new LiveHub({
    engineVersion: 'test',
    topics,
    canSubscribe: (principal) => principal.id !== 'no-role',
    clock: deps.clock,
    timers: deps.timers,
    validateItems: true,
    ...options,
  });
  const client = (principal = createTestPrincipal()) => {
    const sent: { at: number; frame: ServerFrame }[] = [];
    const link = hub.attach(
      {
        send: (text) => {
          sent.push({
            at: deps.clock.monotonic(),
            frame: JSON.parse(text) as ServerFrame,
          });
        },
        close: () => undefined,
        bufferedAmount: 0,
      },
      principal,
    );
    return {
      sent,
      /** The frames since the last call, each with the time it was sent. */
      take: () => sent.splice(0),
      say: async (frame: ClientFrame) => {
        link?.receive(JSON.stringify(frame));
        await deps.timers.settle();
      },
    };
  };
  return { hub, client };
}

const hello: ClientFrame = { t: 'hello', v: 1 };
const sub = (sid: number, params: unknown, credit: number): ClientFrame => ({
  t: 'sub',
  sid,
  topic: topic.id,
  params,
  credit,
});
const watch = (keys: string[], kind = 'queues') => ({ cid: 'c1', kind, keys });

/** What a client holds after the frames: a snapshot replaces its view, a delta edits it. */
function apply(view: Map<string, Item>, frames: ServerFrame[]): void {
  for (const frame of frames) {
    if (frame.t === 'snapshot') {
      view.clear();
      for (const item of frame.items as Item[]) view.set(item.key, item);
    } else if (frame.t === 'delta') {
      for (const item of frame.upserts as Item[]) view.set(item.key, item);
      for (const key of frame.removes) view.delete(key);
    }
  }
}
const deltas = (sent: { frame: ServerFrame }[]) =>
  sent.flatMap(({ frame }) => (frame.t === 'delta' ? [frame] : []));
const problemOf = (frames: ServerFrame[]) =>
  frames.flatMap((f) => (f.t === 'end' && f.problem ? [f.problem] : []))[0];

describe('explorer.window source', () => {
  it('AC-17 explorer.window publishes deltas for visible keys only', async () => {
    const w = setup(20_000, 4);
    const spy = spied(createWindowSource(w.deps));
    const { client } = open(w.deps, spy.source);
    w.deps.sweeper.touch(cid);
    await w.sweep();

    const visible = Array.from({ length: 200 }, (_, i) => w.keyOf(i));
    const shown = new Map<string, Item>();
    const c = client();
    await c.say(hello);
    await c.say(sub(1, watch(visible), 100));
    await w.deps.timers.advance(1_000);
    apply(
      shown,
      c.take().map(({ frame }) => frame),
    );
    // The 200 rows and the version marker reach the client, however the admission raced the snapshot.
    expect([...shown.keys()].sort()).toEqual([...visible, '~version'].sort());
    spy.published.length = 0;

    // Three visible and 500 invisible queues change; the first sweep is sent at once, the next two
    // arrive within 100 ms of each other and must wait for the 2 Hz pace.
    const change = async (messages: number) => {
      for (const i of [10, 11, 12]) w.messages.set(queueName(i), messages);
      for (let i = 1_000; i < 1_500; i++)
        w.messages.set(queueName(i), messages);
      await w.sweep();
    };
    await change(7_000);
    const first = c.take();
    await change(7_001);
    await w.deps.timers.advance(100);
    await change(7_002);
    expect(c.take()).toEqual([]);
    await w.deps.timers.advance(400);
    const later = c.take();

    const own = [10, 11, 12].map((i) => w.keyOf(i)).sort();
    expect(deltas(first).map((f) => f.upserts.length)).toEqual([3]);
    expect(deltas(later).map((f) => f.upserts.length)).toEqual([3]);
    const upserts = [first, later].flatMap((sent) =>
      deltas(sent).flatMap((f) => f.upserts as Item[]),
    );
    expect(
      upserts
        .slice(0, 3)
        .map((i) => i.key)
        .sort(),
    ).toEqual(own);
    // Coalesced: B (7001) was superseded by C (7002) before its turn; each frame is a whole key set.
    expect(upserts.map((i) => i.row?.messages)).toEqual([
      ...[7_000, 7_000, 7_000],
      ...[7_002, 7_002, 7_002],
    ]);
    expect(later.map((s) => s.at - (first[0]?.at ?? 0))).toEqual([500]);
    // The sink saw three sweeps of three visible rows and nothing else; no frame names another queue.
    expect(spy.published).toHaveLength(9);
    expect(new Set(spy.published.map((i) => i.key))).toEqual(new Set(own));
    expect(JSON.stringify([first, later])).not.toMatch(/queue-001[0-4]\d\d/);

    // Unsubscribing stops the source: later sweeps publish nothing.
    await c.say({ t: 'unsub', sid: 1 });
    await change(7_003);
    expect(spy.published).toHaveLength(9);
  });

  it('AC-18 explorer.window removes gone keys and signals a membership change with a version marker', async () => {
    const w = setup(1_050, 2, 2, 20);
    for (let i = 1_000; i < 1_050; i++) w.hidden.add(queueName(i));
    const spy = spied(createWindowSource(w.deps));
    const { client } = open(w.deps, spy.source);
    w.deps.sweeper.touch(cid);
    await w.sweep();
    const c = client();
    await c.say(hello);
    await c.say(
      sub(1, watch(Array.from({ length: 200 }, (_, i) => w.keyOf(i))), 100),
    );
    await w.deps.timers.advance(1_000);
    c.take();
    spy.published.length = 0;

    // Only counts changed (and exchanges left, which this subscription does not follow): the rows
    // are published, no marker.
    w.hidden.add('exchange-1');
    w.messages.set(queueName(3), 9);
    w.messages.set(queueName(4), 9);
    await w.sweep();
    expect(spy.published.map((i) => i.key).sort()).toEqual(
      [w.keyOf(3), w.keyOf(4)].sort(),
    );
    expect(spy.removed).toEqual([]);
    c.take();
    spy.published.length = 0;

    // One visible queue is deleted and 50 are added: a removal, the marker, and no row for a new queue.
    w.hidden.add(queueName(7));
    w.hidden.add(queueName(500)); // gone as well, but not on screen: no removal for it
    for (let i = 1_000; i < 1_050; i++) w.hidden.delete(queueName(i));
    await w.sweep();
    await w.deps.timers.advance(500);
    const version = w.deps.sweeper.index(cid)?.current().version;
    expect(spy.removed).toEqual([w.keyOf(7)]);
    expect(spy.published).toEqual([{ key: '~version', version }]);
    const [frame, ...rest] = deltas(c.take());
    expect(rest).toEqual([]);
    expect(frame?.removes).toEqual([w.keyOf(7)]);
    expect(frame?.upserts).toEqual([{ key: '~version', version }]);

    // The connections kind follows the same rules: the visible rows arrive without their key, a
    // visible connection that left is removed, and the marker says membership changed.
    const connectionName = (i: number) =>
      `connection-${String(i).padStart(6, '0')}`;
    const connectionKey = (i: number) =>
      encodeObjectKey(w.broker.vhosts[i % 2] ?? '', connectionName(i));
    const watched = Array.from({ length: 5 }, (_, i) => connectionKey(i));
    const got: WindowItem[] = [];
    const gone: string[] = [];
    const stop = createWindowSource(w.deps).subscribe(
      topic.params.parse(watch(watched, 'connections')),
      createTestPrincipal(),
      {
        publish: (item) => got.push(item),
        remove: (key) => gone.push(key),
        end: () => undefined,
      },
    );
    await w.deps.timers.settle();
    expect(got.map((item) => item.key).sort()).toEqual(
      [...watched, '~version'].sort(),
    );
    expect(got.find((item) => item.key === connectionKey(2))?.row).toEqual({
      vhost: w.broker.vhosts[0],
      name: connectionName(2),
      user: 'guest',
      node: 'rabbit@fake',
      state: 'running',
      protocol: 'AMQP 0-9-1',
      channels: 2,
      peerHost: '192.0.2.3',
      ssl: false,
    });
    got.length = 0;
    w.hidden.add(connectionName(1));
    w.hidden.add(connectionName(15)); // gone as well, but not on screen
    await w.sweep();
    stop();
    expect(gone).toEqual([connectionKey(1)]);
    expect(got.map((item) => item.key)).toEqual(['~version']);
  });

  it('AC-19 explorer.window snapshot fits one frame and overflow becomes a gap then a snapshot', async () => {
    const BIG = 255;
    const vhost = 'v'.repeat(BIG);
    const bigName = (i: number) =>
      `${String(i).padStart(3, '0')}${'n'.repeat(BIG - 3)}`;
    const strings = (length: number) => ({
      state: 'running',
      node: `rabbit@${'h'.repeat(length - 7)}`,
      policy: 'p'.repeat(length),
      operator_policy: 'o'.repeat(length),
    });
    // 500 queues with 255-character names and vhosts; every sweep changes every count.
    let tick = 0;
    const bigPort = (length: number): MgmtReadPort => ({
      get<T>(request: MgmtGetRequest<T>): Promise<T> {
        const items = request.path.startsWith('/api/queues/')
          ? Array.from({ length: 500 }, (_, i) => ({
              name: bigName(i),
              vhost,
              type: 'quorum',
              durable: true,
              messages: tick * 1_000 + i,
              messages_ready: tick * 1_000 + i,
              messages_unacknowledged: i,
              consumers: i,
              delivery_limit: 2_000_000_000,
              ...strings(length),
            }))
          : [];
        return Promise.resolve(
          request.schema.parse(
            request.path === '/api/vhosts'
              ? [{ name: vhost }]
              : { items, page: 1, page_count: 1, total_count: items.length },
          ),
        );
      },
      stream: () => Promise.reject(new Error('never streams')),
    });
    const keys = Array.from({ length: 500 }, (_, i) =>
      encodeObjectKey(vhost, bigName(i)),
    );
    const params = topic.params.parse(watch(keys));
    const sweepTicks = async (deps: ExplorerFakeDeps, n: number) => {
      for (let i = 0; i < n; i++) {
        tick += 1;
        await deps.sweeper.sweepNow(cid, new AbortController().signal);
      }
    };
    /** The size of the snapshot of a subscription that has been admitted (a plain sink, no hub). */
    const measure = async (deps: ExplorerFakeDeps, source: WindowSource) => {
      const nothing = {
        publish: () => undefined,
        remove: () => undefined,
        end: () => undefined,
      };
      const stop = source.subscribe(params, createTestPrincipal(), nothing);
      await deps.timers.settle();
      const bytes = source.snapshot(params, createTestPrincipal()).bytes;
      stop();
      return bytes;
    };

    // A `sub` naming 500 keys of 255-character names is about 340 KB, well over the hub's default
    // 64 KiB client frame: the carrier must raise `maxClientFrameBytes` (OQ-125 family, see the README).
    const wide = { maxClientFrameBytes: 1024 * 1024 };

    // Typical broker strings: the measured worst-case snapshot fits the frame, and the ring is bounded.
    const deps = createExplorerFakeDeps({ mgmt: bigPort(48) });
    const source = createWindowSource(deps);
    deps.sweeper.touch(cid);
    await sweepTicks(deps, 1);
    const roomy = open(deps, source, wide);
    const a = roomy.client();
    await a.say(hello);
    const welcome = a.take()[0]?.frame;
    if (welcome?.t !== 'welcome') throw new Error('no welcome');
    const { maxFrameBytes } = welcome.limits;
    await a.say(sub(1, watch(keys), 1));
    const measured = await measure(deps, source);
    expect(measured).toBeGreaterThan(700_000);
    expect(measured).toBeLessThanOrEqual(maxFrameBytes);
    await sweepTicks(deps, 3);
    const held = [...roomy.hub.sessions.values()][0]?.live.inspect(1);
    expect(held?.items).toBeLessThanOrEqual(topic.ring.items);
    expect(held?.bytes).toBeLessThanOrEqual(topic.ring.bytes);
    expect(held?.dropped).toBe(0);

    // A session whose outbox budget is smaller than the rows: a client that grants no credit while
    // the index keeps changing gets a gap, then a snapshot, and the loss is counted.
    const tight = open(deps, source, {
      ...wide,
      limits: { outboxBytes: 256 * 1024 },
    });
    const b = tight.client();
    await b.say(hello);
    await b.say(sub(1, watch(keys), 1));
    await sweepTicks(deps, 3);
    const lost = [...tight.hub.sessions.values()][0]?.live.inspect(1);
    expect(lost?.dropped).toBeGreaterThan(0);
    expect(lost?.bytes).toBeLessThanOrEqual(256 * 1024);
    b.take();
    await b.say({ t: 'credit', sid: 1, n: 10 });
    await deps.timers.advance(1_000);
    const [gap, snapshot, ...more] = b.take().map(({ frame }) => frame);
    if (gap?.t !== 'gap' || snapshot?.t !== 'snapshot') {
      throw new Error('expected a gap, then a snapshot');
    }
    expect(more).toEqual([]);
    expect(gap.reason).toBe('overflow');
    expect(gap.toSeq).toBe(snapshot.seq);
    expect(gap.fromSeq).toBeLessThanOrEqual(gap.toSeq);
    expect(snapshot.items).toHaveLength(501);

    // Past the frame, the hub ends the subscription with a Problem: loud, never silent (OQ-125).
    const long = createExplorerFakeDeps({ mgmt: bigPort(BIG) });
    const over = createWindowSource(long);
    long.sweeper.touch(cid);
    await sweepTicks(long, 1);
    expect(await measure(long, over)).toBeGreaterThan(maxFrameBytes);
    const c = open(long, over, wide).client();
    await c.say(hello);
    await c.say(sub(1, watch(keys), 10));
    await long.timers.advance(1_000);
    expect(problemOf(c.take().map(({ frame }) => frame))).toMatchObject({
      code: 'BUDGET_EXCEEDED',
    });
  });

  it('AC-20 explorer.window refuses oversized, forbidden and unknown subscriptions', async () => {
    const w = setup(10, 1);
    const source = createWindowSource(w.deps);
    const spy = spied(source);
    const { client } = open(w.deps, spy.source);
    const ask = async (who: string, params: unknown) => {
      const c = client(createTestPrincipal({ id: who }));
      await c.say(hello);
      c.take();
      await c.say(sub(1, params, 10));
      await w.deps.timers.advance(10);
      return c.take().map(({ frame }) => frame);
    };
    const tooMany = Array.from({ length: 501 }, (_, i) => `key-${String(i)}`);

    // Refused before a source exists: too many keys, an unknown kind, a caller without broker.read.
    expect(problemOf(await ask('user-1', watch(tooMany)))).toMatchObject({
      code: 'VALIDATION_FAILED',
    });
    expect(problemOf(await ask('user-1', watch([], 'bindings')))).toMatchObject(
      { code: 'VALIDATION_FAILED' },
    );
    expect(problemOf(await ask('no-role', watch([])))).toMatchObject({
      code: 'FORBIDDEN_RBAC',
    });
    expect(spy.started()).toBe(0);

    // Someone else's connection and one that does not exist: the same NOT_FOUND, no rows, no index
    // and no request to the broker.
    const hidden = await ask('stranger', watch([w.keyOf(0)]));
    const unknown = await ask('user-1', { ...watch([w.keyOf(0)]), cid: 'c2' });
    const anonymous = (frames: ServerFrame[]) => ({
      ...problemOf(frames),
      correlationId: '',
    });
    expect(anonymous(hidden)).toMatchObject({ code: 'NOT_FOUND' });
    expect(anonymous(hidden)).toEqual(anonymous(unknown));
    expect(JSON.stringify([hidden, unknown])).not.toContain('queue-');
    expect(w.deps.sweeper.index(cid)).toBeUndefined();
    expect(
      w.deps.sweeper.index(ConnectionIdSchema.parse('c2')),
    ).toBeUndefined();
    expect(w.broker.requests).toEqual([]);

    // The 65th subscription of a session is the hub's limit; stopping the source ends the 64 others.
    const c = client();
    await c.say(hello);
    for (let sid = 1; sid <= 64; sid++) await c.say(sub(sid, watch([]), 1));
    c.take();
    await c.say(sub(65, watch([]), 1));
    expect(problemOf(c.take().map(({ frame }) => frame))).toMatchObject({
      code: 'BUDGET_EXCEEDED',
    });
    expect(spy.started()).toBe(2 + 64);
    // The index exists now: a snapshot is for a caller that was admitted, nobody else (one row and
    // the version marker).
    await w.sweep();
    const own = topic.params.parse(watch([w.keyOf(0)]));
    expect(source.snapshot(own, createTestPrincipal()).value).toHaveLength(2);
    expect(
      source.snapshot(own, createTestPrincipal({ id: 'stranger' })).value,
    ).toEqual([]);
    source.stop();
    await w.deps.timers.settle();
    const ended = c
      .take()
      .flatMap(({ frame }) => (frame.t === 'end' ? [frame] : []));
    expect(ended).toHaveLength(64);
    expect(ended.every((f) => f.problem?.code === 'ENGINE_SHUTTING_DOWN')).toBe(
      true,
    );
    // A stopped source takes no new subscription.
    expect(problemOf(await ask('user-1', watch([])))).toMatchObject({
      code: 'ENGINE_SHUTTING_DOWN',
    });
  });
});
